package com.virtualos.agent.agent

import android.content.Context
import com.virtualos.agent.brain.BrainRouter
import com.virtualos.agent.data.security.EncryptedVaultStore
import com.virtualos.agent.data.workspace.SandboxedWorkspaceManager
import com.virtualos.agent.domain.model.AgentActionType
import com.virtualos.agent.domain.model.AgentPhase
import com.virtualos.agent.domain.model.AgentRunStatus
import com.virtualos.agent.domain.model.AgentStepPlan
import com.virtualos.agent.domain.model.BrainRequest
import com.virtualos.agent.domain.model.CredentialCategory
import com.virtualos.agent.domain.model.ExecutionLogEntry
import com.virtualos.agent.domain.model.MemoryCategory
import com.virtualos.agent.limbs.accessibility.AccessibilityBridge
import com.virtualos.agent.limbs.media.VideoEditorLimb
import com.virtualos.agent.limbs.os.ClipboardAndIntentLimb
import com.virtualos.agent.limbs.store.PlayStoreLimb
import com.virtualos.agent.limbs.webview.WebViewAutomationController
import kotlinx.coroutines.CancellationException
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.Job
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.delay
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.isActive
import kotlinx.coroutines.launch
import kotlinx.serialization.json.Json
import java.util.UUID

class AgentOrchestrator(
    private val appContext: Context,
    private val brainRouter: BrainRouter,
    private val vaultStore: EncryptedVaultStore,
    private val workspaceManager: SandboxedWorkspaceManager,
    private val webViewController: WebViewAutomationController,
    private val videoEditorLimb: VideoEditorLimb,
    private val clipboardLimb: ClipboardAndIntentLimb,
    private val playStoreLimb: PlayStoreLimb,
    private val guardrailEngine: GuardrailEngine,
    private val lowMemoryMonitor: LowMemoryMonitor
) {
    private val scope = CoroutineScope(SupervisorJob() + Dispatchers.Default)
    private val json = Json { ignoreUnknownKeys = true; isLenient = true }

    private var activeJob: Job? = null

    private val _status = MutableStateFlow(AgentRunStatus.IDLE)
    val status: StateFlow<AgentRunStatus> = _status.asStateFlow()

    private val _logs = MutableStateFlow<List<ExecutionLogEntry>>(emptyList())
    val logs: StateFlow<List<ExecutionLogEntry>> = _logs.asStateFlow()

    private val _currentStepNumber = MutableStateFlow(0)
    val currentStepNumber: StateFlow<Int> = _currentStepNumber.asStateFlow()

    private val _activeGoal = MutableStateFlow("")
    val activeGoal: StateFlow<String> = _activeGoal.asStateFlow()

    private val _activeVirtualApp = MutableStateFlow<String?>(null)
    val activeVirtualApp: StateFlow<String?> = _activeVirtualApp.asStateFlow()

    fun startTask(goalPrompt: String) {
        val trimmed = goalPrompt.trim()
        if (trimmed.isBlank()) return

        if (activeJob?.isActive == true) {
            appendLog(AgentPhase.SYSTEM, "Task Rejected", "Another task is already active inside Virtual Mobile.")
            return
        }

        _activeGoal.value = trimmed
        _currentStepNumber.value = 0
        _status.value = AgentRunStatus.RUNNING

        activeJob = scope.launch {
            executeLoop(trimmed)
        }
    }

    suspend fun runBlockingForWorker(goalPrompt: String): Result<String> {
        _activeGoal.value = goalPrompt
        _status.value = AgentRunStatus.RUNNING
        return executeLoop(goalPrompt, maxSteps = 8, allowInteractiveGuardrail = false)
    }

    fun pause() {
        if (_status.value == AgentRunStatus.RUNNING) {
            _status.value = AgentRunStatus.PAUSED
            appendLog(AgentPhase.SYSTEM, "Agent Paused", "Execution paused by operator.")
        }
    }

    fun resume() {
        if (_status.value == AgentRunStatus.PAUSED) {
            _status.value = AgentRunStatus.RUNNING
            appendLog(AgentPhase.SYSTEM, "Agent Resumed", "Resuming execution loop.")
        }
    }

    fun stop() {
        guardrailEngine.cancelPending()
        activeJob?.cancel()
        activeJob = null
        _status.value = AgentRunStatus.STOPPED
        appendLog(AgentPhase.SYSTEM, "Agent Stopped", "Execution terminated safely by user.")
    }

    fun clearLogs() {
        _logs.value = emptyList()
    }

    private suspend fun executeLoop(
        goal: String,
        maxSteps: Int = 12,
        allowInteractiveGuardrail: Boolean = true
    ): Result<String> {
        val recentStepOutcomes = ArrayDeque<String>(6)
        var finalSummary = "Task ended."

        try {
            appendLog(AgentPhase.SYSTEM, "Session Started", "Goal: $goal")

            for (stepIndex in 1..maxSteps) {
                while (_status.value == AgentRunStatus.PAUSED) {
                    delay(250L)
                }
                if (!scope.isActive || _status.value == AgentRunStatus.STOPPED) {
                    return Result.failure(CancellationException("Stopped by user"))
                }

                _currentStepNumber.value = stepIndex
                val memoryProfile = lowMemoryMonitor.refreshProfile()
                val skillPolicy = vaultStore.skillSettings.value

                val observation = observeEnvironment(memoryProfile.maxDomCharacters, memoryProfile.maxAccessibilityNodes)
                appendLog(
                    AgentPhase.OBSERVE,
                    "Step $stepIndex Observation",
                    "Virtual RAM: ${memoryProfile.allocatedRamMb / 1024}GB | Apps: ${observation.installedAppsCount} | Memories: ${observation.memoriesCount}"
                )

                val planResult = requestStepPlan(goal, stepIndex, observation, recentStepOutcomes.toList())
                val plan = planResult.getOrElse { err ->
                    appendLog(AgentPhase.ERROR, "Brain Routing Error", err.message ?: "Unknown AI failure")
                    _status.value = AgentRunStatus.FAILED
                    return Result.failure(err)
                }

                appendLog(
                    AgentPhase.PLAN,
                    "Planned: ${plan.action.name}",
                    "Thought: ${plan.thought}\nSteps: ${plan.plannedSteps.joinToString(" -> ")}",
                    providerUsed = planResult.providerLabel
                )

                if (plan.isDone || plan.action == AgentActionType.FINISH_TASK) {
                    finalSummary = plan.finalSummary.ifBlank { plan.thought }
                    appendLog(AgentPhase.VERIFY, "Task Completed", finalSummary)
                    _status.value = AgentRunStatus.COMPLETED
                    persistHistoryReport(goal, finalSummary, recentStepOutcomes.toList())
                    return Result.success(finalSummary)
                }

                val guardrail = guardrailEngine.classifyRisk(plan, skillPolicy)
                if (guardrail != null) {
                    if (!allowInteractiveGuardrail) {
                        val blockedMsg = "Background worker blocked sensitive action ${plan.action.name} without live UI approval."
                        appendLog(AgentPhase.GUARDRAIL, "Blocked in Background", blockedMsg)
                        _status.value = AgentRunStatus.FAILED
                        return Result.failure(SecurityException(blockedMsg))
                    }
                    _status.value = AgentRunStatus.AWAITING_CONFIRMATION
                    appendLog(AgentPhase.GUARDRAIL, "Awaiting User Confirmation", "${guardrail.reason} Target: ${guardrail.target}")
                    val approved = guardrailEngine.requestUserApproval(guardrail)
                    if (!approved) {
                        _status.value = AgentRunStatus.STOPPED
                        appendLog(AgentPhase.GUARDRAIL, "Action Denied", "Operator denied ${plan.action.name}. Halting safely.")
                        return Result.failure(SecurityException("Action denied by user"))
                    }
                    _status.value = AgentRunStatus.RUNNING
                    appendLog(AgentPhase.GUARDRAIL, "Action Approved", "Operator authorized ${plan.action.name}.")
                }

                val actionOutcome = executeActionSafely(plan)
                val outcomePhase = when {
                    plan.action.name.startsWith("VIDEO_") -> AgentPhase.MEDIA
                    plan.action.name.startsWith("PLAY_STORE_") || plan.action == AgentActionType.OPEN_VIRTUAL_APP -> AgentPhase.STORE
                    plan.action.name.startsWith("CREDENTIAL_") || plan.action == AgentActionType.MEMORY_SAVE || plan.action == AgentActionType.PAYMENT_METHOD_SAVE -> AgentPhase.MEMORY
                    else -> AgentPhase.ACT
                }
                val outcomeText = actionOutcome.fold(
                    onSuccess = { msg ->
                        appendLog(outcomePhase, "Executed ${plan.action.name}", msg)
                        "Step $stepIndex OK (${plan.action.name}): $msg"
                    },
                    onFailure = { err ->
                        val recovered = "Step $stepIndex RECOVERED ERROR (${plan.action.name}): ${err.message}"
                        appendLog(AgentPhase.VERIFY, "Step Failed Safely", recovered)
                        recovered
                    }
                )

                if (recentStepOutcomes.size >= 5) recentStepOutcomes.removeFirst()
                recentStepOutcomes.addLast(outcomeText)
                delay(350L)
            }

            finalSummary = "Reached $maxSteps step safety budget. Partial progress saved to workspace."
            appendLog(AgentPhase.VERIFY, "Step Limit Reached", finalSummary)
            _status.value = AgentRunStatus.COMPLETED
            persistHistoryReport(goal, finalSummary, recentStepOutcomes.toList())
            return Result.success(finalSummary)
        } catch (ce: CancellationException) {
            _status.value = AgentRunStatus.STOPPED
            return Result.failure(ce)
        } catch (t: Throwable) {
            appendLog(AgentPhase.ERROR, "Orchestrator Exception", t.message ?: "Unexpected failure")
            _status.value = AgentRunStatus.FAILED
            return Result.failure(t)
        }
    }

    private suspend fun observeEnvironment(maxDomChars: Int, maxAccNodes: Int): EnvironmentObservation {
        val webObs = webViewController.observation.value
        val domPreview = webObs.domSummaryJson.take(maxDomChars / 2)
        val workspaceFiles = workspaceManager.listFilesSummary().take(1000)
        val accessibilityConnected = AccessibilityBridge.isConnected.value
        val accessibilityTree = if (accessibilityConnected) {
            AccessibilityBridge.readScreenTree(maxNodes = maxAccNodes).getOrDefault("Unavailable")
        } else {
            "Accessibility Service disabled"
        }
        val profileContext = vaultStore.userProfile.value.toCompactAgentContext()
        val credentialSummary = vaultStore.credentials.value.joinToString("\n") {
            "- ${it.serviceName} (${it.category.name}): user=${it.usernameOrEmail} | location=${it.savedLocationPath}"
        }.ifBlank { "None stored yet." }
        val paymentSummary = vaultStore.paymentMethods.value.joinToString("\n") {
            "- ${it.label} (${it.provider} ${it.maskedIdentifier}) | location=${it.savedLocationPath}"
        }.ifBlank { "None stored yet." }
        val memorySummary = vaultStore.memories.value.joinToString("\n") {
            "- [${it.category.name}] ${it.title}: ${it.content}"
        }.ifBlank { "None stored yet." }
        val virtualApps = vaultStore.virtualApps.value.joinToString(", ") {
            "${it.appName} (${it.packageId})"
        }.ifBlank { "None installed yet." }

        return EnvironmentObservation(
            webUrl = webObs.url,
            webTitle = webObs.title,
            webDom = domPreview,
            workspaceSummary = workspaceFiles,
            accessibilityPackage = AccessibilityBridge.activePackage.value,
            accessibilityTree = accessibilityTree,
            userProfile = profileContext,
            credentialsSummary = credentialSummary,
            paymentsSummary = paymentSummary,
            memoriesSummary = memorySummary,
            virtualAppsSummary = virtualApps,
            installedAppsCount = vaultStore.virtualApps.value.size,
            memoriesCount = vaultStore.memories.value.size
        )
    }

    private suspend fun requestStepPlan(
        goal: String,
        stepIndex: Int,
        obs: EnvironmentObservation,
        recentHistory: List<String>
    ): PlanCallEnvelope {
        val skills = vaultStore.skillSettings.value
        val systemPrompt = """
            You are KaryoOS, an autonomous isolated Virtual Phone & OS Agent inside Android.
            You understand Bengali (বাংলা) and English fluently.
            When the user asks to download/install an app (WhatsApp, imo, Telegram, Calling, etc.), use PLAY_STORE_SEARCH / PLAY_STORE_INSTALL and OPEN_VIRTUAL_APP inside the isolated phone.
            When the user gives important info, addresses, preferences, or asks you to remember/save account/password/payment details so they don't have to repeat it, use MEMORY_SAVE, CREDENTIAL_SAVE, CREDENTIAL_GENERATE_AND_SAVE, or PAYMENT_METHOD_SAVE, and explicitly report the exact saved location path (e.g. "Vault -> Credentials -> WhatsApp") in finalSummary!
            Respond ONLY with valid JSON:
            {
              "thought": "concise reasoning",
              "phaseNote": "short status note in user's language",
              "plannedSteps": ["step 1", "step 2"],
              "action": "ONE_OF_ENUM",
              "target": "URL, selector, app name, service name, file path, video URI, or memory title",
              "value": "payload value (for CREDENTIAL_SAVE use 'username|password|notes'; for PAYMENT_METHOD_SAVE use 'provider|maskedIdentifier|billingAddress'; for MEMORY_SAVE use 'CATEGORY|content')",
              "requiresConfirmation": false,
              "riskReason": "",
              "isDone": false,
              "finalSummary": ""
            }
            Enabled Skills:
            - Play Store & Virtual Apps (${skills.playStoreInstallEnabled}): PLAY_STORE_SEARCH, PLAY_STORE_INSTALL, OPEN_VIRTUAL_APP
            - Credentials, Payment Metadata & Self-Improving Memory (${skills.autoMemoryLearningEnabled}): CREDENTIAL_SAVE, CREDENTIAL_GENERATE_AND_SAVE, PAYMENT_METHOD_SAVE, MEMORY_SAVE
            - Web Automation (${skills.webAutomationEnabled}): WEB_NAVIGATE, WEB_EXTRACT_DOM, WEB_FILL_INPUT, WEB_CLICK_ELEMENT, WEB_SCROLL
            - File Workspace (${skills.fileWorkspaceEnabled}): WORKSPACE_WRITE_FILE, WORKSPACE_READ_FILE, WORKSPACE_LIST_FILES, WORKSPACE_DELETE_FILE
            - OS Accessibility (${skills.accessibilityControlEnabled}): ACCESSIBILITY_READ_SCREEN, ACCESSIBILITY_CLICK_NODE, ACCESSIBILITY_TYPE_TEXT, ACCESSIBILITY_SCROLL, ACCESSIBILITY_GLOBAL_BACK, LAUNCH_APP
            - Video Editing Media3 (${skills.videoEditingEnabled}): VIDEO_TRIM, VIDEO_RESIZE_COMPRESS, VIDEO_MUTE, VIDEO_WATERMARK
            - Clipboard & Share (${skills.clipboardAndShareEnabled}): CLIPBOARD_SET, SEND_SHARE_INTENT
            - Sensitive Actions: SUBMIT_SENSITIVE_FORM, ACCOUNT_LOGIN_OR_SIGNUP, PAYMENT_ACTION
            - Completion: FINISH_TASK
        """.trimIndent()

        val userPrompt = """
            USER GOAL: $goal
            CURRENT STEP: $stepIndex
            USER PROFILE VAULT:
            ${obs.userProfile}

            SAVED CREDENTIALS INDEX:
            ${obs.credentialsSummary}

            SAVED PAYMENT METHODS:
            ${obs.paymentsSummary}

            PERSISTENT MEMORIES & ADDRESSES (NEVER ASK AGAIN FOR THESE):
            ${obs.memoriesSummary}

            INSTALLED VIRTUAL PHONE APPS:
            ${obs.virtualAppsSummary}

            WEBVIEW STATE (${obs.webUrl} - ${obs.webTitle}):
            ${obs.webDom}

            ACCESSIBILITY ACTIVE APP (${obs.accessibilityPackage}):
            ${obs.accessibilityTree}

            SANDBOXED WORKSPACE FILES:
            ${obs.workspaceSummary}

            RECENT STEP OUTCOMES:
            ${if (recentHistory.isEmpty()) "None yet." else recentHistory.joinToString("\n")}
        """.trimIndent()

        val response = brainRouter.routeGenerate(
            BrainRequest(
                systemInstruction = systemPrompt,
                userPrompt = userPrompt,
                jsonMode = true,
                maxTokens = 1200
            )
        ).getOrElse { return PlanCallEnvelope.Failure(it) }

        val cleanedJson = extractJsonObject(response.rawText)
        val parsed = runCatching { json.decodeFromString<AgentStepPlan>(cleanedJson) }
            .getOrElse { err ->
                return PlanCallEnvelope.Failure(
                    IllegalStateException("Invalid JSON from ${response.modelId}: ${err.message}")
                )
            }

        return PlanCallEnvelope.Success(
            plan = parsed,
            providerLabel = "${response.provider.name}:${response.modelId} (${response.keyLabel}, ${response.latencyMs}ms)"
        )
    }

    private suspend fun executeActionSafely(plan: AgentStepPlan): Result<String> {
        val skills = vaultStore.skillSettings.value
        return when (plan.action) {
            AgentActionType.PLAY_STORE_SEARCH -> {
                if (!skills.playStoreInstallEnabled) return Result.failure(IllegalStateException("Play Store disabled in Settings"))
                val results = playStoreLimb.searchCatalog(plan.target)
                Result.success("Play Store matches: ${results.joinToString { "${it.appName} (${it.packageId})" }}")
            }
            AgentActionType.PLAY_STORE_INSTALL -> {
                if (!skills.playStoreInstallEnabled) return Result.failure(IllegalStateException("Play Store disabled in Settings"))
                playStoreLimb.installApp(plan.target).map { app ->
                    _activeVirtualApp.value = app.appName
                    "Installed ${app.appName} (${app.packageId}) into Virtual Phone Drawer."
                }
            }
            AgentActionType.OPEN_VIRTUAL_APP -> {
                val app = playStoreLimb.searchCatalog(plan.target).first()
                _activeVirtualApp.value = app.appName
                webViewController.navigate(app.webFallbackUrl)
                Result.success("Opened ${app.appName} inside Virtual Phone viewport (${app.webFallbackUrl})")
            }

            AgentActionType.CREDENTIAL_GENERATE_AND_SAVE -> {
                val parts = plan.value.split("|")
                val userOrEmail = parts.getOrNull(0)?.trim()?.ifBlank {
                    vaultStore.userProfile.value.email.ifBlank { "user@karyoos.local" }
                } ?: "user@karyoos.local"
                val generatedPass = vaultStore.generateStrongPassword(16)
                val notes = parts.getOrNull(1)?.trim() ?: "Auto-generated secure password"
                val entry = vaultStore.saveCredential(
                    serviceName = plan.target,
                    usernameOrEmail = userOrEmail,
                    secretValue = generatedPass,
                    category = CredentialCategory.APP_ACCOUNT,
                    notes = notes
                )
                Result.success("Saved account for ${entry.serviceName} (user: ${entry.usernameOrEmail}) at ${entry.savedLocationPath}")
            }
            AgentActionType.CREDENTIAL_SAVE -> {
                val parts = plan.value.split("|")
                val userOrEmail = parts.getOrNull(0)?.trim() ?: ""
                val pass = parts.getOrNull(1)?.trim()?.ifBlank { vaultStore.generateStrongPassword(16) }
                    ?: vaultStore.generateStrongPassword(16)
                val notes = parts.getOrNull(2)?.trim() ?: ""
                val entry = vaultStore.saveCredential(
                    serviceName = plan.target,
                    usernameOrEmail = userOrEmail,
                    secretValue = pass,
                    category = CredentialCategory.APP_ACCOUNT,
                    notes = notes
                )
                Result.success("Saved credential at ${entry.savedLocationPath} (Username: ${entry.usernameOrEmail})")
            }
            AgentActionType.PAYMENT_METHOD_SAVE -> {
                val parts = plan.value.split("|")
                val provider = parts.getOrNull(0)?.trim()?.ifBlank { "Wallet/Card" } ?: "Wallet/Card"
                val masked = parts.getOrNull(1)?.trim()?.ifBlank { "****" } ?: "****"
                val billing = parts.getOrNull(2)?.trim() ?: vaultStore.userProfile.value.location
                val entry = vaultStore.savePaymentMethod(
                    label = plan.target.ifBlank { provider },
                    provider = provider,
                    maskedIdentifier = masked,
                    billingAddress = billing
                )
                Result.success("Saved payment method (${entry.provider} ${entry.maskedIdentifier}) at ${entry.savedLocationPath}")
            }
            AgentActionType.MEMORY_SAVE -> {
                val parts = plan.value.split("|", limit = 2)
                val cat = if (parts.size == 2) {
                    runCatching { MemoryCategory.valueOf(parts[0].trim().uppercase()) }
                        .getOrDefault(MemoryCategory.IMPORTANT_NOTE)
                } else MemoryCategory.IMPORTANT_NOTE
                val body = if (parts.size == 2) parts[1].trim() else plan.value
                val saved = vaultStore.saveMemoryNote(
                    title = plan.target.ifBlank { "User Note" },
                    content = body,
                    category = cat
                )
                Result.success("Remembered permanently at ${saved.savedLocationPath}")
            }

            AgentActionType.WEB_NAVIGATE -> {
                if (!skills.webAutomationEnabled) return Result.failure(IllegalStateException("Web skill disabled in Settings"))
                webViewController.navigate(plan.target)
            }
            AgentActionType.WEB_EXTRACT_DOM -> {
                if (!skills.webAutomationEnabled) return Result.failure(IllegalStateException("Web skill disabled in Settings"))
                webViewController.extractDomSnapshot(lowMemoryMonitor.memoryProfile.value.maxDomCharacters)
            }
            AgentActionType.WEB_FILL_INPUT -> webViewController.fillInput(plan.target, plan.value)
            AgentActionType.WEB_CLICK_ELEMENT,
            AgentActionType.SUBMIT_SENSITIVE_FORM,
            AgentActionType.ACCOUNT_LOGIN_OR_SIGNUP,
            AgentActionType.PAYMENT_ACTION -> webViewController.clickElement(plan.target)
            AgentActionType.WEB_SCROLL -> webViewController.scrollPage(plan.value.ifBlank { "down" })

            AgentActionType.WORKSPACE_WRITE_FILE -> workspaceManager.writeFile(plan.target, plan.value)
                .map { "Saved ${it.relativePath} (${it.sizeBytes} bytes)" }
            AgentActionType.WORKSPACE_READ_FILE -> workspaceManager.readFile(plan.target)
            AgentActionType.WORKSPACE_LIST_FILES -> Result.success(workspaceManager.listFilesSummary())
            AgentActionType.WORKSPACE_DELETE_FILE -> workspaceManager.deleteFile(plan.target)
                .map { "Deleted ${plan.target}" }

            AgentActionType.ACCESSIBILITY_READ_SCREEN -> AccessibilityBridge.readScreenTree(
                lowMemoryMonitor.memoryProfile.value.maxAccessibilityNodes
            )
            AgentActionType.ACCESSIBILITY_CLICK_NODE -> AccessibilityBridge.clickNode(plan.target)
            AgentActionType.ACCESSIBILITY_TYPE_TEXT -> AccessibilityBridge.typeText(plan.target, plan.value)
            AgentActionType.ACCESSIBILITY_SCROLL -> AccessibilityBridge.scrollScreen(!plan.value.equals("up", ignoreCase = true))
            AgentActionType.ACCESSIBILITY_GLOBAL_BACK -> AccessibilityBridge.performBack()
            AgentActionType.LAUNCH_APP -> AccessibilityBridge.launchAppByPackageOrName(appContext, plan.target)

            AgentActionType.CLIPBOARD_SET -> clipboardLimb.copyToClipboard(plan.target, plan.value)
            AgentActionType.SEND_SHARE_INTENT -> clipboardLimb.shareTextIntent(plan.target, plan.value)

            AgentActionType.VIDEO_TRIM -> {
                if (!skills.videoEditingEnabled) return Result.failure(IllegalStateException("Video editing skill disabled in Settings"))
                val parts = plan.value.split(":", "-", ",")
                val startMs = parts.getOrNull(0)?.trim()?.toLongOrNull() ?: 0L
                val endMs = parts.getOrNull(1)?.trim()?.toLongOrNull() ?: 10_000L
                videoEditorLimb.trimVideo(plan.target, startMs, endMs)
            }
            AgentActionType.VIDEO_RESIZE_COMPRESS -> {
                if (!skills.videoEditingEnabled) return Result.failure(IllegalStateException("Video editing skill disabled in Settings"))
                val height = plan.value.trim().toIntOrNull() ?: 720
                videoEditorLimb.resizeAndCompressVideo(plan.target, height)
            }
            AgentActionType.VIDEO_MUTE -> {
                if (!skills.videoEditingEnabled) return Result.failure(IllegalStateException("Video editing skill disabled in Settings"))
                videoEditorLimb.muteVideo(plan.target)
            }
            AgentActionType.VIDEO_WATERMARK -> {
                if (!skills.videoEditingEnabled) return Result.failure(IllegalStateException("Video editing skill disabled in Settings"))
                videoEditorLimb.addTextWatermark(plan.target, plan.value)
            }

            AgentActionType.FINISH_TASK -> Result.success(plan.finalSummary)
        }
    }

    private suspend fun persistHistoryReport(goal: String, summary: String, steps: List<String>) {
        val fileName = "history/run_${System.currentTimeMillis()}.md"
        val body = buildString {
            appendLine("# KaryoOS Execution Report")
            appendLine("- **Goal**: $goal")
            appendLine("- **Summary**: $summary")
            appendLine("\n## Steps")
            steps.forEach { appendLine("- $it") }
        }
        workspaceManager.writeFile(fileName, body)
    }

    private fun extractJsonObject(raw: String): String {
        val trimmed = raw.trim()
            .removePrefix("```json")
            .removePrefix("```")
            .removeSuffix("```")
            .trim()
        val start = trimmed.indexOf('{')
        val end = trimmed.lastIndexOf('}')
        return if (start >= 0 && end > start) trimmed.substring(start, end + 1) else trimmed
    }

    private fun appendLog(phase: AgentPhase, title: String, detail: String, providerUsed: String? = null) {
        val cap = lowMemoryMonitor.memoryProfile.value.maxLogEntries
        val entry = ExecutionLogEntry(
            id = UUID.randomUUID().toString(),
            timestampMs = System.currentTimeMillis(),
            phase = phase,
            title = title,
            detail = detail,
            providerUsed = providerUsed
        )
        _logs.value = (_logs.value + entry).takeLast(cap)
    }

    private data class EnvironmentObservation(
        val webUrl: String,
        val webTitle: String,
        val webDom: String,
        val workspaceSummary: String,
        val accessibilityPackage: String,
        val accessibilityTree: String,
        val userProfile: String,
        val credentialsSummary: String,
        val paymentsSummary: String,
        val memoriesSummary: String,
        val virtualAppsSummary: String,
        val installedAppsCount: Int,
        val memoriesCount: Int
    )

    private sealed class PlanCallEnvelope {
        data class Success(val plan: AgentStepPlan, val providerLabel: String) : PlanCallEnvelope()
        data class Failure(val error: Throwable) : PlanCallEnvelope()

        inline fun getOrElse(onFailure: (Throwable) -> AgentStepPlan): AgentStepPlan = when (this) {
            is Success -> plan
            is Failure -> onFailure(error)
        }

        val providerLabel: String?
            get() = (this as? Success)?.providerLabel
    }
}

package com.virtualos.agent.agent

import com.virtualos.agent.domain.model.AgentActionType
import com.virtualos.agent.domain.model.AgentStepPlan
import com.virtualos.agent.domain.model.GuardrailRequest
import com.virtualos.agent.domain.model.RiskLevel
import com.virtualos.agent.domain.model.SkillSettingsConfig
import kotlinx.coroutines.CompletableDeferred
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import java.util.UUID

class GuardrailEngine {

    private val _pendingConfirmation = MutableStateFlow<GuardrailRequest?>(null)
    val pendingConfirmation: StateFlow<GuardrailRequest?> = _pendingConfirmation.asStateFlow()

    private var activeDecision: CompletableDeferred<Boolean>? = null

    fun classifyRisk(plan: AgentStepPlan, policy: SkillSettingsConfig = SkillSettingsConfig()): GuardrailRequest? {
        val sensitiveKeywords = listOf(
            "submit", "apply", "pay", "checkout", "purchase", "confirm order",
            "sign in", "login", "register", "delete", "remove", "send email"
        )
        val combinedTarget = "${plan.target} ${plan.value} ${plan.phaseNote}".lowercase()

        val riskLevel: RiskLevel? = when (plan.action) {
            AgentActionType.PAYMENT_ACTION -> RiskLevel.CRITICAL
            AgentActionType.SUBMIT_SENSITIVE_FORM,
            AgentActionType.ACCOUNT_LOGIN_OR_SIGNUP -> if (policy.requireConfirmOnSubmit) RiskLevel.HIGH else null
            AgentActionType.WORKSPACE_DELETE_FILE -> if (policy.requireConfirmOnDelete) RiskLevel.MEDIUM else null
            AgentActionType.SEND_SHARE_INTENT -> if (policy.requireConfirmOnExternalShare) RiskLevel.MEDIUM else null
            AgentActionType.WEB_CLICK_ELEMENT,
            AgentActionType.ACCESSIBILITY_CLICK_NODE -> {
                if (policy.requireConfirmOnSubmit && sensitiveKeywords.any { combinedTarget.contains(it) }) {
                    RiskLevel.HIGH
                } else null
            }
            else -> if (plan.requiresConfirmation) RiskLevel.MEDIUM else null
        }

        if (riskLevel == null) return null

        return GuardrailRequest(
            stepId = UUID.randomUUID().toString(),
            action = plan.action,
            target = plan.target,
            proposedValue = plan.value,
            reason = plan.riskReason.ifBlank {
                "Sensitive or irreversible action detected (${plan.action.name}). Explicit approval required."
            },
            riskLevel = riskLevel
        )
    }

    suspend fun requestUserApproval(request: GuardrailRequest): Boolean {
        val deferred = CompletableDeferred<Boolean>()
        activeDecision = deferred
        _pendingConfirmation.value = request
        return try {
            deferred.await()
        } finally {
            _pendingConfirmation.value = null
            activeDecision = null
        }
    }

    fun resolveConfirmation(approved: Boolean) {
        activeDecision?.complete(approved)
    }

    fun cancelPending() {
        activeDecision?.complete(false)
        _pendingConfirmation.value = null
        activeDecision = null
    }
}

package com.virtualos.agent.agent

import android.app.ActivityManager
import android.content.ComponentCallbacks2
import android.content.Context
import android.content.res.Configuration
import com.virtualos.agent.data.security.EncryptedVaultStore
import com.virtualos.agent.domain.model.MemoryProfile
import com.virtualos.agent.limbs.webview.WebViewAutomationController
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow

/**
 * Dynamically configures the Virtual Mobile Environment based on user-selected RAM allocation
 * (1 GB, 2 GB, 4 GB, 6 GB, 8 GB, 12 GB, 16 GB) relative to host device RAM.
 */
class LowMemoryMonitor(
    context: Context,
    private val vaultStore: EncryptedVaultStore,
    private val webViewController: WebViewAutomationController
) : ComponentCallbacks2 {

    private val activityManager = context.getSystemService(Context.ACTIVITY_SERVICE) as ActivityManager

    private val _memoryProfile = MutableStateFlow(sampleMemoryProfile())
    val memoryProfile: StateFlow<MemoryProfile> = _memoryProfile.asStateFlow()

    fun refreshProfile(): MemoryProfile {
        val sampled = sampleMemoryProfile()
        _memoryProfile.value = sampled
        webViewController.applyMemoryProfile(!sampled.webViewImagesEnabled)
        return sampled
    }

    private fun sampleMemoryProfile(): MemoryProfile {
        val info = ActivityManager.MemoryInfo()
        activityManager.getMemoryInfo(info)
        val totalHostMb = (info.totalMem / (1024L * 1024L)).coerceAtLeast(1024L)
        val availHostMb = info.availMem / (1024L * 1024L)

        val envCfg = vaultStore.virtualEnvConfig.value
        val allocatedMb = (envCfg.allocatedRamGb * 1024f).toLong().coerceIn(1024L, 16384L)
        val hostReservedMb = (totalHostMb - allocatedMb).coerceAtLeast(0L)
        val lowMode = envCfg.lowMemoryOptimizationEnabled || allocatedMb <= 4096L || info.lowMemory

        val (maxTasks, maxLogs, maxDomChars, maxAccNodes, quotaMb) = when {
            allocatedMb <= 2048L -> Quintuple(1, 80, 3500, 30, 64)
            allocatedMb <= 4096L -> Quintuple(1, 150, 5500, 45, 256)
            allocatedMb <= 8192L -> Quintuple(2, 300, 9000, 75, 512)
            else -> Quintuple(3, 500, 14000, 110, 1024)
        }

        return MemoryProfile(
            envName = envCfg.envName,
            allocatedRamMb = allocatedMb,
            lowMemoryModeEnabled = lowMode,
            totalHostRamMb = totalHostMb,
            availableHostRamMb = availHostMb,
            hostReservedRamMb = hostReservedMb,
            maxConcurrentTasks = maxTasks,
            maxLogEntries = maxLogs,
            maxDomCharacters = maxDomChars,
            maxAccessibilityNodes = maxAccNodes,
            webViewImagesEnabled = allocatedMb > 4096L && !info.lowMemory,
            workspaceQuotaMb = quotaMb
        )
    }

    override fun onTrimMemory(level: Int) {
        if (level >= ComponentCallbacks2.TRIM_MEMORY_RUNNING_LOW) {
            webViewController.trimMemory(lowMemoryMode = true)
        }
        refreshProfile()
    }

    override fun onConfigurationChanged(newConfig: Configuration) = Unit

    override fun onLowMemory() {
        webViewController.trimMemory(lowMemoryMode = true)
        refreshProfile()
    }

    private data class Quintuple(
        val maxTasks: Int,
        val maxLogs: Int,
        val maxDomChars: Int,
        val maxAccNodes: Int,
        val quotaMb: Int
    )
}

package com.virtualos.agent.brain

import com.virtualos.agent.data.security.EncryptedVaultStore
import com.virtualos.agent.domain.model.AiProvider
import com.virtualos.agent.domain.model.ApiKeyEntry
import com.virtualos.agent.domain.model.BrainRequest
import com.virtualos.agent.domain.model.BrainResponse
import com.virtualos.agent.domain.model.BrainRouterConfig
import com.virtualos.agent.domain.model.KeyRotationEvent
import com.virtualos.agent.domain.model.RouteDiagnosticResult
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.atomic.AtomicInteger

/**
 * Production Multi-Key + Multi-Model Cascade Router:
 * - Rotates across 5+ Free Gemini API keys (separate Gmail accounts) using LRU + round-robin.
 * - Uses 1 single OpenRouter API key to cascade across all configured OpenRouter `:free` models.
 * - Tracks per-(keyId + modelId) cooldowns independently so a 429 on one OpenRouter free model
 *   never blocks the other free models on the same OpenRouter key.
 */
class BrainRouter(
    private val vaultStore: EncryptedVaultStore,
    private val geminiClient: GeminiClient,
    private val openRouterClient: OpenRouterClient
) {
    private val routeMutex = Mutex()
    private val geminiRoundRobinCursor = AtomicInteger(0)

    // Keyed by "${key.id}::${modelId}" -> cooldown expiry epoch ms
    private val routeCooldownMap = ConcurrentHashMap<String, Long>()

    private val _rotationHistory = MutableStateFlow<List<KeyRotationEvent>>(emptyList())
    val rotationHistory: StateFlow<List<KeyRotationEvent>> = _rotationHistory.asStateFlow()

    suspend fun routeGenerate(request: BrainRequest): Result<BrainResponse> = routeMutex.withLock {
        val now = System.currentTimeMillis()
        val config = vaultStore.routerConfig.value
        val allKeys = vaultStore.apiKeys.value.filter { it.enabled && it.apiKey.isNotBlank() }

        if (allKeys.isEmpty()) {
            return Result.failure(
                IllegalStateException("No API keys configured. Add up to 5 free Gemini keys and/or 1 OpenRouter key in Brain Settings.")
            )
        }

        val candidates = buildCandidateChain(allKeys, config, now)
        if (candidates.isEmpty()) {
            return Result.failure(
                IllegalStateException("All configured Gemini keys & OpenRouter free models are currently cooling down. Reset cooldowns or wait.")
            )
        }

        var rotationCount = 0
        var lastError = "All provider routes exhausted"
        var previousRouteLabel: String? = null

        for (candidate in candidates) {
            val currentRouteLabel = "${candidate.key.label} [${candidate.modelId}]"
            if (previousRouteLabel != null && previousRouteLabel != currentRouteLabel) {
                rotationCount++
                recordRotation(
                    from = previousRouteLabel,
                    to = currentRouteLabel,
                    reason = lastError
                )
            }
            previousRouteLabel = currentRouteLabel

            val result = when (candidate.provider) {
                AiProvider.GEMINI -> geminiClient.generate(candidate.key.apiKey, candidate.modelId, request)
                AiProvider.OPENROUTER -> openRouterClient.generate(candidate.key.apiKey, candidate.modelId, request)
            }

            when (result) {
                is BrainCallResult.Success -> {
                    routeCooldownMap.remove(routeKey(candidate.key.id, candidate.modelId))
                    vaultStore.markKeySuccess(candidate.key.id)
                    return Result.success(
                        BrainResponse(
                            rawText = result.text,
                            provider = candidate.provider,
                            modelId = candidate.modelId,
                            keyLabel = candidate.key.label,
                            latencyMs = result.latencyMs,
                            rotationCount = rotationCount
                        )
                    )
                }

                is BrainCallResult.Failure -> {
                    lastError = result.message
                    val nowErr = System.currentTimeMillis()
                    val rKey = routeKey(candidate.key.id, candidate.modelId)

                    if (candidate.provider == AiProvider.OPENROUTER && !result.isAuthError) {
                        // Cool down ONLY this specific free model so the same OpenRouter key can try other :free models immediately!
                        val modelCooldownMs = if (result.isRateLimitOrQuota) {
                            config.modelCooldownSeconds * 1000L
                        } else {
                            20_000L
                        }
                        routeCooldownMap[rKey] = nowErr + modelCooldownMs
                    } else {
                        val keyCooldownMs = when {
                            result.isAuthError -> 3600_000L
                            result.isRateLimitOrQuota -> config.keyCooldownSeconds * 1000L
                            result.isTransientNetwork -> 15_000L
                            else -> 30_000L
                        }
                        routeCooldownMap[rKey] = nowErr + keyCooldownMs
                        vaultStore.markKeyCooldown(
                            id = candidate.key.id,
                            cooldownUntilMs = nowErr + keyCooldownMs,
                            errorMessage = result.message,
                            isAuthInvalid = result.isAuthError
                        )
                    }
                }
            }
        }

        Result.failure(RuntimeException("BrainRouter exhausted ${candidates.size} routes. Last error: $lastError"))
    }

    suspend fun testAllConfiguredRoutes(): List<RouteDiagnosticResult> {
        val allKeys = vaultStore.apiKeys.value.filter { it.enabled && it.apiKey.isNotBlank() }
        val config = vaultStore.routerConfig.value
        val probeReq = BrainRequest(
            systemInstruction = "Reply with JSON {\"ok\":true}",
            userPrompt = "Ping",
            jsonMode = true,
            maxTokens = 32
        )
        val diagnostics = mutableListOf<RouteDiagnosticResult>()

        val primaryGeminiModel = config.geminiModels.firstOrNull() ?: "gemini-2.5-flash"
        allKeys.filter { it.provider == AiProvider.GEMINI }.forEach { key ->
            val res = geminiClient.generate(key.apiKey, primaryGeminiModel, probeReq)
            diagnostics.add(
                when (res) {
                    is BrainCallResult.Success -> RouteDiagnosticResult(
                        AiProvider.GEMINI, key.label, primaryGeminiModel, true, res.latencyMs, "Healthy"
                    )
                    is BrainCallResult.Failure -> RouteDiagnosticResult(
                        AiProvider.GEMINI, key.label, primaryGeminiModel, false, 0L, res.message
                    )
                }
            )
        }

        val orKeys = allKeys.filter { it.provider == AiProvider.OPENROUTER }
        if (orKeys.isNotEmpty()) {
            val primaryOrKey = orKeys.first()
            config.openRouterFreeModels.forEach { freeModel ->
                val res = openRouterClient.generate(primaryOrKey.apiKey, freeModel, probeReq)
                diagnostics.add(
                    when (res) {
                        is BrainCallResult.Success -> RouteDiagnosticResult(
                            AiProvider.OPENROUTER, primaryOrKey.label, freeModel, true, res.latencyMs, "Healthy"
                        )
                        is BrainCallResult.Failure -> RouteDiagnosticResult(
                            AiProvider.OPENROUTER, primaryOrKey.label, freeModel, false, 0L, res.message
                        )
                    }
                )
            }
        }

        return diagnostics
    }

    fun clearRouteCooldowns() {
        routeCooldownMap.clear()
        vaultStore.resetAllCooldowns()
    }

    private fun buildCandidateChain(
        allKeys: List<ApiKeyEntry>,
        config: BrainRouterConfig,
        nowMs: Long
    ): List<RouteCandidate> {
        val geminiKeys = orderGeminiKeysLru(allKeys.filter { it.provider == AiProvider.GEMINI }, nowMs)
        val openRouterKeys = allKeys.filter { it.provider == AiProvider.OPENROUTER }

        val geminiModels = config.geminiModels.ifEmpty { listOf("gemini-2.5-flash") }
        val openRouterModels = config.openRouterFreeModels.ifEmpty { listOf("google/gemini-2.0-flash-exp:free") }

        val geminiCandidates = mutableListOf<RouteCandidate>()
        // Rotate across all 5 Gemini keys on primary model first, then try secondary Gemini free models
        for (modelId in geminiModels) {
            for (key in geminiKeys) {
                val rKey = routeKey(key.id, modelId)
                val modelWait = routeCooldownMap[rKey] ?: 0L
                if (key.cooldownUntilEpochMs <= nowMs && modelWait <= nowMs) {
                    geminiCandidates.add(RouteCandidate(AiProvider.GEMINI, modelId, key))
                }
            }
        }

        val openRouterCandidates = mutableListOf<RouteCandidate>()
        // 1 OpenRouter key cascades across every free model in priority order
        for (key in openRouterKeys) {
            for (freeModel in openRouterModels) {
                val rKey = routeKey(key.id, freeModel)
                val modelWait = routeCooldownMap[rKey] ?: 0L
                if (modelWait <= nowMs) {
                    openRouterCandidates.add(RouteCandidate(AiProvider.OPENROUTER, freeModel, key))
                }
            }
        }

        val combined = if (config.primaryProvider == AiProvider.GEMINI) {
            geminiCandidates + openRouterCandidates
        } else {
            openRouterCandidates + geminiCandidates
        }

        if (combined.isNotEmpty()) {
            return combined.take(config.maxAttemptsPerCall.coerceAtLeast(1))
        }

        // Emergency fallback if everything is in cooldown: pick any enabled keys & models
        val fallback = mutableListOf<RouteCandidate>()
        geminiKeys.forEach { fallback.add(RouteCandidate(AiProvider.GEMINI, geminiModels.first(), it)) }
        openRouterKeys.forEach { key ->
            openRouterModels.forEach { m -> fallback.add(RouteCandidate(AiProvider.OPENROUTER, m, key)) }
        }
        return fallback.take(config.maxAttemptsPerCall.coerceAtLeast(1))
    }

    private fun orderGeminiKeysLru(keys: List<ApiKeyEntry>, nowMs: Long): List<ApiKeyEntry> {
        if (keys.size <= 1) return keys
        val ready = keys.filter { it.cooldownUntilEpochMs <= nowMs }
            .sortedBy { it.lastUsedEpochMs }
        val cooling = keys.filter { it.cooldownUntilEpochMs > nowMs }
            .sortedBy { it.cooldownUntilEpochMs }
        val ordered = ready + cooling
        val offset = Math.floorMod(geminiRoundRobinCursor.getAndIncrement(), ordered.size)
        return ordered.drop(offset) + ordered.take(offset)
    }

    private fun routeKey(keyId: String, modelId: String): String = "$keyId::$modelId"

    private fun recordRotation(from: String, to: String, reason: String) {
        val event = KeyRotationEvent(
            timestampMs = System.currentTimeMillis(),
            fromRoute = from,
            toRoute = to,
            reason = reason.take(140)
        )
        _rotationHistory.value = (listOf(event) + _rotationHistory.value).take(40)
    }

    private data class RouteCandidate(
        val provider: AiProvider,
        val modelId: String,
        val key: ApiKeyEntry
    )
}

package com.virtualos.agent.brain

import com.virtualos.agent.domain.model.BrainRequest
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import kotlinx.serialization.json.Json
import kotlinx.serialization.json.JsonArray
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.JsonPrimitive
import kotlinx.serialization.json.buildJsonObject
import kotlinx.serialization.json.jsonArray
import kotlinx.serialization.json.jsonObject
import kotlinx.serialization.json.jsonPrimitive
import kotlinx.serialization.json.put
import kotlinx.serialization.json.putJsonArray
import kotlinx.serialization.json.putJsonObject
import okhttp3.MediaType.Companion.toMediaType
import okhttp3.OkHttpClient
import okhttp3.Request
import okhttp3.RequestBody.Companion.toRequestBody
import java.io.IOException

sealed class BrainCallResult {
    data class Success(val text: String, val latencyMs: Long) : BrainCallResult()
    data class Failure(
        val httpCode: Int,
        val isRateLimitOrQuota: Boolean,
        val isAuthError: Boolean,
        val isTransientNetwork: Boolean,
        val message: String
    ) : BrainCallResult()
}

class GeminiClient(
    private val httpClient: OkHttpClient
) {
    private val json = Json { ignoreUnknownKeys = true }

    suspend fun generate(
        apiKey: String,
        modelId: String,
        request: BrainRequest
    ): BrainCallResult = withContext(Dispatchers.IO) {
        val started = System.currentTimeMillis()
        val endpoint = "https://generativelanguage.googleapis.com/v1beta/models/$modelId:generateContent?key=$apiKey"

        val payload = buildJsonObject {
            putJsonObject("systemInstruction") {
                putJsonArray("parts") {
                    add(buildJsonObject { put("text", request.systemInstruction) })
                }
            }
            putJsonArray("contents") {
                add(buildJsonObject {
                    put("role", "user")
                    putJsonArray("parts") {
                        add(buildJsonObject { put("text", request.userPrompt) })
                    }
                })
            }
            putJsonObject("generationConfig") {
                put("temperature", 0.2)
                put("maxOutputTokens", request.maxTokens)
                if (request.jsonMode) {
                    put("responseMimeType", "application/json")
                }
            }
        }

        val httpRequest = Request.Builder()
            .url(endpoint)
            .post(payload.toString().toRequestBody(JSON_MEDIA_TYPE))
            .header("Content-Type", "application/json")
            .build()

        try {
            httpClient.newCall(httpRequest).execute().use { response ->
                val rawBody = response.body?.string().orEmpty()
                val latency = System.currentTimeMillis() - started

                if (!response.isSuccessful) {
                    val code = response.code
                    val isQuota = code == 429 || rawBody.contains("RESOURCE_EXHAUSTED", ignoreCase = true)
                    val isAuth = code == 401 || code == 403 || rawBody.contains("API_KEY_INVALID", ignoreCase = true)
                    val isTransient = code >= 500 || code == 408
                    return@withContext BrainCallResult.Failure(
                        httpCode = code,
                        isRateLimitOrQuota = isQuota,
                        isAuthError = isAuth,
                        isTransientNetwork = isTransient,
                        message = "Gemini HTTP $code: ${extractErrorMessage(rawBody)}"
                    )
                }

                val root = json.parseToJsonElement(rawBody).jsonObject
                val text = root["candidates"]
                    ?.jsonArray
                    ?.firstOrNull()
                    ?.jsonObject
                    ?.get("content")
                    ?.jsonObject
                    ?.get("parts")
                    ?.jsonArray
                    ?.firstOrNull()
                    ?.jsonObject
                    ?.get("text")
                    ?.jsonPrimitive
                    ?.content

                if (text.isNullOrBlank()) {
                    BrainCallResult.Failure(
                        httpCode = 200,
                        isRateLimitOrQuota = false,
                        isAuthError = false,
                        isTransientNetwork = false,
                        message = "Gemini returned empty candidate text"
                    )
                } else {
                    BrainCallResult.Success(text = text, latencyMs = latency)
                }
            }
        } catch (io: IOException) {
            BrainCallResult.Failure(
                httpCode = -1,
                isRateLimitOrQuota = false,
                isAuthError = false,
                isTransientNetwork = true,
                message = "Gemini network error: ${io.message ?: "IOException"}"
            )
        } catch (t: Throwable) {
            BrainCallResult.Failure(
                httpCode = -1,
                isRateLimitOrQuota = false,
                isAuthError = false,
                isTransientNetwork = false,
                message = "Gemini parse error: ${t.message ?: "Unknown"}"
            )
        }
    }

    private fun extractErrorMessage(rawBody: String): String {
        return runCatching {
            val obj = json.parseToJsonElement(rawBody).jsonObject
            obj["error"]?.jsonObject?.get("message")?.jsonPrimitive?.content ?: rawBody.take(180)
        }.getOrDefault(rawBody.take(180))
    }

    companion object {
        private val JSON_MEDIA_TYPE = "application/json; charset=utf-8".toMediaType()
    }
}

package com.virtualos.agent.brain

import com.virtualos.agent.domain.model.BrainRequest
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import kotlinx.serialization.json.Json
import kotlinx.serialization.json.buildJsonObject
import kotlinx.serialization.json.jsonArray
import kotlinx.serialization.json.jsonObject
import kotlinx.serialization.json.jsonPrimitive
import kotlinx.serialization.json.put
import kotlinx.serialization.json.putJsonArray
import kotlinx.serialization.json.putJsonObject
import okhttp3.MediaType.Companion.toMediaType
import okhttp3.OkHttpClient
import okhttp3.Request
import okhttp3.RequestBody.Companion.toRequestBody
import java.io.IOException

class OpenRouterClient(
    private val httpClient: OkHttpClient
) {
    private val json = Json { ignoreUnknownKeys = true }

    suspend fun generate(
        apiKey: String,
        modelId: String,
        request: BrainRequest
    ): BrainCallResult = withContext(Dispatchers.IO) {
        val started = System.currentTimeMillis()
        val payload = buildJsonObject {
            put("model", modelId)
            put("temperature", 0.2)
            put("max_tokens", request.maxTokens)
            if (request.jsonMode) {
                putJsonObject("response_format") {
                    put("type", "json_object")
                }
            }
            putJsonArray("messages") {
                add(buildJsonObject {
                    put("role", "system")
                    put("content", request.systemInstruction)
                })
                add(buildJsonObject {
                    put("role", "user")
                    put("content", request.userPrompt)
                })
            }
        }

        val httpRequest = Request.Builder()
            .url(OPENROUTER_ENDPOINT)
            .post(payload.toString().toRequestBody(JSON_MEDIA_TYPE))
            .header("Authorization", "Bearer $apiKey")
            .header("HTTP-Referer", "https://karyoos.local.agent")
            .header("X-Title", "KaryoOS Android Agent")
            .header("Content-Type", "application/json")
            .build()

        try {
            httpClient.newCall(httpRequest).execute().use { response ->
                val rawBody = response.body?.string().orEmpty()
                val latency = System.currentTimeMillis() - started

                if (!response.isSuccessful) {
                    val code = response.code
                    val isQuota = code == 429 || code == 402 || rawBody.contains("rate", ignoreCase = true)
                    val isAuth = code == 401 || code == 403
                    val isTransient = code >= 500 || code == 408
                    return@withContext BrainCallResult.Failure(
                        httpCode = code,
                        isRateLimitOrQuota = isQuota,
                        isAuthError = isAuth,
                        isTransientNetwork = isTransient,
                        message = "OpenRouter HTTP $code: ${extractError(rawBody)}"
                    )
                }

                val root = json.parseToJsonElement(rawBody).jsonObject
                val content = root["choices"]
                    ?.jsonArray
                    ?.firstOrNull()
                    ?.jsonObject
                    ?.get("message")
                    ?.jsonObject
                    ?.get("content")
                    ?.jsonPrimitive
                    ?.content

                if (content.isNullOrBlank()) {
                    BrainCallResult.Failure(
                        httpCode = 200,
                        isRateLimitOrQuota = false,
                        isAuthError = false,
                        isTransientNetwork = false,
                        message = "OpenRouter returned empty message content"
                    )
                } else {
                    BrainCallResult.Success(text = content, latencyMs = latency)
                }
            }
        } catch (io: IOException) {
            BrainCallResult.Failure(
                httpCode = -1,
                isRateLimitOrQuota = false,
                isAuthError = false,
                isTransientNetwork = true,
                message = "OpenRouter network error: ${io.message ?: "IOException"}"
            )
        } catch (t: Throwable) {
            BrainCallResult.Failure(
                httpCode = -1,
                isRateLimitOrQuota = false,
                isAuthError = false,
                isTransientNetwork = false,
                message = "OpenRouter parse error: ${t.message ?: "Unknown"}"
            )
        }
    }

    private fun extractError(rawBody: String): String {
        return runCatching {
            val obj = json.parseToJsonElement(rawBody).jsonObject
            obj["error"]?.jsonObject?.get("message")?.jsonPrimitive?.content ?: rawBody.take(180)
        }.getOrDefault(rawBody.take(180))
    }

    companion object {
        private const val OPENROUTER_ENDPOINT = "https://openrouter.ai/api/v1/chat/completions"
        private val JSON_MEDIA_TYPE = "application/json; charset=utf-8".toMediaType()
    }
}

package com.virtualos.agent.data.queue

import android.content.Context
import androidx.room.Dao
import androidx.room.Database
import androidx.room.Entity
import androidx.room.Insert
import androidx.room.OnConflictStrategy
import androidx.room.PrimaryKey
import androidx.room.Query
import androidx.room.Room
import androidx.room.RoomDatabase
import com.virtualos.agent.domain.model.ScheduledTask
import com.virtualos.agent.domain.model.TaskQueueStatus
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.map

@Entity(tableName = "scheduled_tasks")
data class ScheduledTaskEntity(
    @PrimaryKey val id: String,
    val title: String,
    val prompt: String,
    val isRecurring: Boolean,
    val intervalHours: Long,
    val requiresUnmeteredNetwork: Boolean,
    val requiresBatteryNotLow: Boolean,
    val status: String,
    val createdAtMs: Long,
    val lastRunAtMs: Long?,
    val lastResultSummary: String?
) {
    fun toDomain(): ScheduledTask = ScheduledTask(
        id = id,
        title = title,
        prompt = prompt,
        isRecurring = isRecurring,
        intervalHours = intervalHours,
        requiresUnmeteredNetwork = requiresUnmeteredNetwork,
        requiresBatteryNotLow = requiresBatteryNotLow,
        status = runCatching { TaskQueueStatus.valueOf(status) }.getOrDefault(TaskQueueStatus.QUEUED),
        createdAtMs = createdAtMs,
        lastRunAtMs = lastRunAtMs,
        lastResultSummary = lastResultSummary
    )

    companion object {
        fun fromDomain(task: ScheduledTask): ScheduledTaskEntity = ScheduledTaskEntity(
            id = task.id,
            title = task.title,
            prompt = task.prompt,
            isRecurring = task.isRecurring,
            intervalHours = task.intervalHours,
            requiresUnmeteredNetwork = task.requiresUnmeteredNetwork,
            requiresBatteryNotLow = task.requiresBatteryNotLow,
            status = task.status.name,
            createdAtMs = task.createdAtMs,
            lastRunAtMs = task.lastRunAtMs,
            lastResultSummary = task.lastResultSummary
        )
    }
}

@Dao
interface ScheduledTaskDao {
    @Query("SELECT * FROM scheduled_tasks ORDER BY createdAtMs DESC")
    fun observeAll(): Flow<List<ScheduledTaskEntity>>

    @Query("SELECT * FROM scheduled_tasks WHERE id = :id LIMIT 1")
    suspend fun getById(id: String): ScheduledTaskEntity?

    @Insert(onConflict = OnConflictStrategy.REPLACE)
    suspend fun upsert(entity: ScheduledTaskEntity)

    @Query("UPDATE scheduled_tasks SET status = :status, lastRunAtMs = :lastRunAtMs, lastResultSummary = :summary WHERE id = :id")
    suspend fun updateExecutionResult(id: String, status: String, lastRunAtMs: Long, summary: String)

    @Query("DELETE FROM scheduled_tasks WHERE id = :id")
    suspend fun deleteById(id: String)
}

@Database(entities = [ScheduledTaskEntity::class], version = 1, exportSchema = false)
abstract class TaskQueueDatabase : RoomDatabase() {
    abstract fun scheduledTaskDao(): ScheduledTaskDao

    fun observeDomainTasks(): Flow<List<ScheduledTask>> =
        scheduledTaskDao().observeAll().map { rows -> rows.map { it.toDomain() } }

    companion object {
        @Volatile
        private var INSTANCE: TaskQueueDatabase? = null

        fun getInstance(context: Context): TaskQueueDatabase {
            return INSTANCE ?: synchronized(this) {
                INSTANCE ?: Room.databaseBuilder(
                    context.applicationContext,
                    TaskQueueDatabase::class.java,
                    "karyo_task_queue.db"
                ).fallbackToDestructiveMigration().build().also { INSTANCE = it }
            }
        }
    }
}

package com.virtualos.agent.data.security

import android.content.Context
import android.content.SharedPreferences
import androidx.security.crypto.EncryptedSharedPreferences
import androidx.security.crypto.MasterKey
import com.virtualos.agent.domain.model.AiProvider
import com.virtualos.agent.domain.model.ApiKeyEntry
import com.virtualos.agent.domain.model.BrainRouterConfig
import com.virtualos.agent.domain.model.CredentialCategory
import com.virtualos.agent.domain.model.CredentialEntry
import com.virtualos.agent.domain.model.KeyHealthStatus
import com.virtualos.agent.domain.model.MemoryCategory
import com.virtualos.agent.domain.model.MemoryNoteEntry
import com.virtualos.agent.domain.model.PaymentMethodEntry
import com.virtualos.agent.domain.model.SkillSettingsConfig
import com.virtualos.agent.domain.model.UserProfileVault
import com.virtualos.agent.domain.model.VirtualAppEntry
import com.virtualos.agent.domain.model.VirtualEnvironmentConfig
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.serialization.encodeToString
import kotlinx.serialization.json.Json
import java.security.MessageDigest
import java.security.SecureRandom
import java.util.UUID

/**
 * AES-256 EncryptedSharedPreferences store for:
 * - 5+ Gemini free keys + OpenRouter key
 * - Virtual Mobile RAM & Sandbox settings
 * - Skills & Guardrails policy
 * - User Profile Vault, Credentials/Passwords, Payment Metadata, Persistent AI Memories,
 *   Installed Virtual Play Store Apps, and Privacy PIN lock hash.
 */
class EncryptedVaultStore(context: Context) {

    private val json = Json {
        ignoreUnknownKeys = true
        encodeDefaults = true
    }

    private val masterKey: MasterKey = MasterKey.Builder(context)
        .setKeyScheme(MasterKey.KeyScheme.AES256_GCM)
        .build()

    private val prefs: SharedPreferences = EncryptedSharedPreferences.create(
        context,
        PREFS_FILE_NAME,
        masterKey,
        EncryptedSharedPreferences.PrefKeyEncryptionScheme.AES256_SIV,
        EncryptedSharedPreferences.PrefValueEncryptionScheme.AES256_GCM
    )

    private val _apiKeys = MutableStateFlow(loadApiKeysInternal())
    val apiKeys: StateFlow<List<ApiKeyEntry>> = _apiKeys.asStateFlow()

    private val _routerConfig = MutableStateFlow(loadRouterConfigInternal())
    val routerConfig: StateFlow<BrainRouterConfig> = _routerConfig.asStateFlow()

    private val _userProfile = MutableStateFlow(loadUserProfileInternal())
    val userProfile: StateFlow<UserProfileVault> = _userProfile.asStateFlow()

    private val _virtualEnvConfig = MutableStateFlow(loadVirtualEnvConfigInternal())
    val virtualEnvConfig: StateFlow<VirtualEnvironmentConfig> = _virtualEnvConfig.asStateFlow()

    private val _skillSettings = MutableStateFlow(loadSkillSettingsInternal())
    val skillSettings: StateFlow<SkillSettingsConfig> = _skillSettings.asStateFlow()

    private val _credentials = MutableStateFlow(loadCredentialsInternal())
    val credentials: StateFlow<List<CredentialEntry>> = _credentials.asStateFlow()

    private val _paymentMethods = MutableStateFlow(loadPaymentMethodsInternal())
    val paymentMethods: StateFlow<List<PaymentMethodEntry>> = _paymentMethods.asStateFlow()

    private val _memories = MutableStateFlow(loadMemoriesInternal())
    val memories: StateFlow<List<MemoryNoteEntry>> = _memories.asStateFlow()

    private val _virtualApps = MutableStateFlow(loadVirtualAppsInternal())
    val virtualApps: StateFlow<List<VirtualAppEntry>> = _virtualApps.asStateFlow()

    private val _hasPrivacyPin = MutableStateFlow(prefs.getString(KEY_PRIVACY_PIN_HASH, null) != null)
    val hasPrivacyPin: StateFlow<Boolean> = _hasPrivacyPin.asStateFlow()

    fun addApiKey(
        label: String,
        provider: AiProvider,
        rawKey: String,
        accountHint: String = ""
    ) {
        val trimmed = rawKey.trim()
        if (trimmed.isBlank()) return
        val existingCount = _apiKeys.value.count { it.provider == provider }
        val updated = _apiKeys.value + ApiKeyEntry(
            id = UUID.randomUUID().toString(),
            label = label.ifBlank { "${provider.name} #${existingCount + 1}" },
            provider = provider,
            apiKey = trimmed,
            accountHint = accountHint.trim(),
            enabled = true
        )
        persistApiKeys(updated)
    }

    fun upsertBatchGeminiKeys(entries: List<Triple<String, String, String>>) {
        val nonGemini = _apiKeys.value.filter { it.provider != AiProvider.GEMINI }
        val existingGemini = _apiKeys.value.filter { it.provider == AiProvider.GEMINI }
        val newGemini = entries.mapIndexedNotNull { idx, (label, accountHint, rawKey) ->
            val trimmed = rawKey.trim()
            if (trimmed.isBlank()) return@mapIndexedNotNull null
            val existing = existingGemini.firstOrNull { it.apiKey == trimmed }
            existing?.copy(
                label = label.ifBlank { existing.label },
                accountHint = accountHint.ifBlank { existing.accountHint },
                enabled = true
            ) ?: ApiKeyEntry(
                id = UUID.randomUUID().toString(),
                label = label.ifBlank { "Gemini Gmail #${idx + 1}" },
                provider = AiProvider.GEMINI,
                apiKey = trimmed,
                accountHint = accountHint.trim(),
                enabled = true
            )
        }
        persistApiKeys(newGemini + nonGemini)
    }

    fun removeApiKey(id: String) = persistApiKeys(_apiKeys.value.filterNot { it.id == id })

    fun toggleApiKeyEnabled(id: String) {
        val updated = _apiKeys.value.map { entry ->
            if (entry.id == id) {
                entry.copy(
                    enabled = !entry.enabled,
                    cooldownUntilEpochMs = 0L,
                    healthStatus = KeyHealthStatus.READY
                )
            } else entry
        }
        persistApiKeys(updated)
    }

    fun markKeySuccess(id: String) {
        val now = System.currentTimeMillis()
        val updated = _apiKeys.value.map { entry ->
            if (entry.id == id) {
                entry.copy(
                    successCount = entry.successCount + 1,
                    lastUsedEpochMs = now,
                    cooldownUntilEpochMs = 0L,
                    healthStatus = KeyHealthStatus.READY,
                    lastError = null
                )
            } else entry
        }
        persistApiKeys(updated)
    }

    fun markKeyCooldown(
        id: String,
        cooldownUntilMs: Long,
        errorMessage: String,
        isAuthInvalid: Boolean = false
    ) {
        val updated = _apiKeys.value.map { entry ->
            if (entry.id == id) {
                entry.copy(
                    cooldownUntilEpochMs = cooldownUntilMs,
                    failureCount = entry.failureCount + 1,
                    lastUsedEpochMs = System.currentTimeMillis(),
                    lastError = errorMessage.take(180),
                    healthStatus = if (isAuthInvalid) KeyHealthStatus.AUTH_INVALID else KeyHealthStatus.COOLDOWN
                )
            } else entry
        }
        persistApiKeys(updated)
    }

    fun resetAllCooldowns() {
        val updated = _apiKeys.value.map {
            it.copy(
                cooldownUntilEpochMs = 0L,
                healthStatus = KeyHealthStatus.READY,
                lastError = null
            )
        }
        persistApiKeys(updated)
    }

    fun saveCredential(
        serviceName: String,
        usernameOrEmail: String,
        secretValue: String,
        category: CredentialCategory = CredentialCategory.APP_ACCOUNT,
        notes: String = ""
    ): CredentialEntry {
        val cleanService = serviceName.trim().ifBlank { "Service" }
        val entry = CredentialEntry(
            id = UUID.randomUUID().toString(),
            serviceName = cleanService,
            category = category,
            usernameOrEmail = usernameOrEmail.trim(),
            secretValue = secretValue,
            savedLocationPath = "Vault -> Credentials -> $cleanService",
            notes = notes.trim(),
            updatedAtMs = System.currentTimeMillis()
        )
        val updated = _credentials.value.filterNot {
            it.serviceName.equals(cleanService, ignoreCase = true) &&
                it.usernameOrEmail.equals(entry.usernameOrEmail, ignoreCase = true)
        } + entry
        _credentials.value = updated
        prefs.edit().putString(KEY_CREDENTIALS, json.encodeToString(updated)).apply()
        return entry
    }

    fun deleteCredential(id: String) {
        val updated = _credentials.value.filterNot { it.id == id }
        _credentials.value = updated
        prefs.edit().putString(KEY_CREDENTIALS, json.encodeToString(updated)).apply()
    }

    fun generateStrongPassword(length: Int = 16): String {
        val charset = "ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!@#$%&*"
        val random = SecureRandom()
        return buildString {
            repeat(length.coerceIn(12, 32)) {
                append(charset[random.nextInt(charset.length)])
            }
        }
    }

    fun savePaymentMethod(
        label: String,
        provider: String,
        maskedIdentifier: String,
        billingAddress: String = "",
        notes: String = ""
    ): PaymentMethodEntry {
        val cleanLabel = label.trim().ifBlank { provider }
        val entry = PaymentMethodEntry(
            id = UUID.randomUUID().toString(),
            label = cleanLabel,
            provider = provider.trim(),
            maskedIdentifier = maskedIdentifier.trim(),
            billingAddress = billingAddress.trim(),
            savedLocationPath = "Vault -> Payments -> $cleanLabel",
            notes = notes.trim(),
            updatedAtMs = System.currentTimeMillis()
        )
        val updated = _paymentMethods.value.filterNot { it.label.equals(cleanLabel, ignoreCase = true) } + entry
        _paymentMethods.value = updated
        prefs.edit().putString(KEY_PAYMENTS, json.encodeToString(updated)).apply()
        return entry
    }

    fun deletePaymentMethod(id: String) {
        val updated = _paymentMethods.value.filterNot { it.id == id }
        _paymentMethods.value = updated
        prefs.edit().putString(KEY_PAYMENTS, json.encodeToString(updated)).apply()
    }

    fun saveMemoryNote(
        title: String,
        content: String,
        category: MemoryCategory = MemoryCategory.IMPORTANT_NOTE
    ): MemoryNoteEntry {
        val cleanTitle = title.trim().ifBlank { "Note" }
        val entry = MemoryNoteEntry(
            id = UUID.randomUUID().toString(),
            category = category,
            title = cleanTitle,
            content = content.trim(),
            savedLocationPath = "Vault -> Memory -> $cleanTitle",
            updatedAtMs = System.currentTimeMillis()
        )
        val updated = _memories.value.filterNot { it.title.equals(cleanTitle, ignoreCase = true) } + entry
        _memories.value = updated
        prefs.edit().putString(KEY_MEMORIES, json.encodeToString(updated)).apply()
        return entry
    }

    fun deleteMemoryNote(id: String) {
        val updated = _memories.value.filterNot { it.id == id }
        _memories.value = updated
        prefs.edit().putString(KEY_MEMORIES, json.encodeToString(updated)).apply()
    }

    fun upsertVirtualApp(app: VirtualAppEntry) {
        val updated = _virtualApps.value.filterNot { it.packageId == app.packageId } + app
        _virtualApps.value = updated
        prefs.edit().putString(KEY_VIRTUAL_APPS, json.encodeToString(updated)).apply()
    }

    fun setPrivacyPin(rawPin: String) {
        val trimmed = rawPin.trim()
        if (trimmed.isBlank()) {
            prefs.edit().remove(KEY_PRIVACY_PIN_HASH).apply()
            _hasPrivacyPin.value = false
            return
        }
        prefs.edit().putString(KEY_PRIVACY_PIN_HASH, sha256(trimmed)).apply()
        _hasPrivacyPin.value = true
    }

    fun verifyPrivacyPin(candidatePin: String): Boolean {
        val stored = prefs.getString(KEY_PRIVACY_PIN_HASH, null) ?: return true
        return stored == sha256(candidatePin.trim())
    }

    fun updateRouterConfig(config: BrainRouterConfig) {
        _routerConfig.value = config
        prefs.edit().putString(KEY_ROUTER_CONFIG, json.encodeToString(config)).apply()
    }

    fun updateUserProfile(profile: UserProfileVault) {
        _userProfile.value = profile
        prefs.edit().putString(KEY_USER_PROFILE, json.encodeToString(profile)).apply()
    }

    fun updateVirtualEnvConfig(config: VirtualEnvironmentConfig) {
        val clampedRam = config.allocatedRamGb.coerceIn(1.0f, 16.0f)
        val normalized = config.copy(allocatedRamGb = clampedRam)
        _virtualEnvConfig.value = normalized
        prefs.edit().putString(KEY_VIRTUAL_ENV, json.encodeToString(normalized)).apply()
    }

    fun updateSkillSettings(config: SkillSettingsConfig) {
        _skillSettings.value = config
        prefs.edit().putString(KEY_SKILL_SETTINGS, json.encodeToString(config)).apply()
    }

    private fun sha256(value: String): String {
        val bytes = MessageDigest.getInstance("SHA-256").digest(value.toByteArray(Charsets.UTF_8))
        return bytes.joinToString("") { "%02x".format(it) }
    }

    private fun persistApiKeys(list: List<ApiKeyEntry>) {
        _apiKeys.value = list
        prefs.edit().putString(KEY_API_KEYS, json.encodeToString(list)).apply()
    }

    private fun loadApiKeysInternal(): List<ApiKeyEntry> {
        val raw = prefs.getString(KEY_API_KEYS, null) ?: return emptyList()
        return runCatching { json.decodeFromString<List<ApiKeyEntry>>(raw) }.getOrDefault(emptyList())
    }

    private fun loadRouterConfigInternal(): BrainRouterConfig {
        val raw = prefs.getString(KEY_ROUTER_CONFIG, null) ?: return BrainRouterConfig()
        return runCatching { json.decodeFromString<BrainRouterConfig>(raw) }.getOrDefault(BrainRouterConfig())
    }

    private fun loadUserProfileInternal(): UserProfileVault {
        val raw = prefs.getString(KEY_USER_PROFILE, null) ?: return UserProfileVault()
        return runCatching { json.decodeFromString<UserProfileVault>(raw) }.getOrDefault(UserProfileVault())
    }

    private fun loadVirtualEnvConfigInternal(): VirtualEnvironmentConfig {
        val raw = prefs.getString(KEY_VIRTUAL_ENV, null) ?: return VirtualEnvironmentConfig()
        return runCatching { json.decodeFromString<VirtualEnvironmentConfig>(raw) }
            .getOrDefault(VirtualEnvironmentConfig())
    }

    private fun loadSkillSettingsInternal(): SkillSettingsConfig {
        val raw = prefs.getString(KEY_SKILL_SETTINGS, null) ?: return SkillSettingsConfig()
        return runCatching { json.decodeFromString<SkillSettingsConfig>(raw) }
            .getOrDefault(SkillSettingsConfig())
    }

    private fun loadCredentialsInternal(): List<CredentialEntry> {
        val raw = prefs.getString(KEY_CREDENTIALS, null) ?: return emptyList()
        return runCatching { json.decodeFromString<List<CredentialEntry>>(raw) }.getOrDefault(emptyList())
    }

    private fun loadPaymentMethodsInternal(): List<PaymentMethodEntry> {
        val raw = prefs.getString(KEY_PAYMENTS, null) ?: return emptyList()
        return runCatching { json.decodeFromString<List<PaymentMethodEntry>>(raw) }.getOrDefault(emptyList())
    }

    private fun loadMemoriesInternal(): List<MemoryNoteEntry> {
        val raw = prefs.getString(KEY_MEMORIES, null) ?: return emptyList()
        return runCatching { json.decodeFromString<List<MemoryNoteEntry>>(raw) }.getOrDefault(emptyList())
    }

    private fun loadVirtualAppsInternal(): List<VirtualAppEntry> {
        val raw = prefs.getString(KEY_VIRTUAL_APPS, null) ?: return emptyList()
        return runCatching { json.decodeFromString<List<VirtualAppEntry>>(raw) }.getOrDefault(emptyList())
    }

    companion object {
        private const val PREFS_FILE_NAME = "karyo_encrypted_vault"
        private const val KEY_API_KEYS = "api_keys_json"
        private const val KEY_ROUTER_CONFIG = "router_config_json"
        private const val KEY_USER_PROFILE = "user_profile_json"
        private const val KEY_VIRTUAL_ENV = "virtual_env_config_json"
        private const val KEY_SKILL_SETTINGS = "skill_settings_json"
        private const val KEY_CREDENTIALS = "credentials_json"
        private const val KEY_PAYMENTS = "payments_json"
        private const val KEY_MEMORIES = "memories_json"
        private const val KEY_VIRTUAL_APPS = "virtual_apps_json"
        private const val KEY_PRIVACY_PIN_HASH = "privacy_pin_hash"
    }
}

package com.virtualos.agent.data.workspace

import android.content.Context
import com.virtualos.agent.domain.model.WorkspaceFileEntry
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.withContext
import java.io.File

/**
 * Sandboxed virtual filesystem inside app-private storage (`filesDir/agent_workspace/`).
 * Enforces canonical path confinement to prevent directory traversal outside the workspace.
 */
class SandboxedWorkspaceManager(context: Context) {

    private val rootDir: File = File(context.filesDir, WORKSPACE_ROOT_FOLDER).apply {
        if (!exists()) mkdirs()
        SUBFOLDERS.forEach { folder ->
            File(this, folder).apply { if (!exists()) mkdirs() }
        }
    }

    private val _files = MutableStateFlow<List<WorkspaceFileEntry>>(emptyList())
    val files: StateFlow<List<WorkspaceFileEntry>> = _files.asStateFlow()

    init {
        refreshSync()
    }

    suspend fun refresh(): List<WorkspaceFileEntry> = withContext(Dispatchers.IO) {
        refreshSync()
    }

    private fun refreshSync(): List<WorkspaceFileEntry> {
        val collected = mutableListOf<WorkspaceFileEntry>()
        rootDir.walkTopDown()
            .filter { it != rootDir }
            .sortedWith(compareBy({ !it.isDirectory }, { it.relativeTo(rootDir).path }))
            .forEach { file ->
                val rel = file.relativeTo(rootDir).path.replace(File.separatorChar, '/')
                val folder = rel.substringBefore('/', "root")
                collected.add(
                    WorkspaceFileEntry(
                        relativePath = rel,
                        name = file.name,
                        folder = folder,
                        sizeBytes = if (file.isFile) file.length() else 0L,
                        lastModifiedMs = file.lastModified(),
                        isDirectory = file.isDirectory
                    )
                )
            }
        _files.value = collected
        return collected
    }

    suspend fun writeFile(relativePath: String, content: String): Result<WorkspaceFileEntry> =
        withContext(Dispatchers.IO) {
            runCatching {
                val target = resolveConfinedFile(relativePath)
                require(content.toByteArray(Charsets.UTF_8).size <= MAX_FILE_BYTES) {
                    "File exceeds 512 KB low-memory safety limit"
                }
                target.parentFile?.let { if (!it.exists()) it.mkdirs() }
                target.writeText(content, Charsets.UTF_8)
                refreshSync()
                val rel = target.relativeTo(rootDir).path.replace(File.separatorChar, '/')
                WorkspaceFileEntry(
                    relativePath = rel,
                    name = target.name,
                    folder = rel.substringBefore('/', "root"),
                    sizeBytes = target.length(),
                    lastModifiedMs = target.lastModified(),
                    isDirectory = false
                )
            }
        }

    suspend fun readFile(relativePath: String, maxChars: Int = 12000): Result<String> =
        withContext(Dispatchers.IO) {
            runCatching {
                val target = resolveConfinedFile(relativePath)
                require(target.exists() && target.isFile) { "File not found: $relativePath" }
                val text = target.readText(Charsets.UTF_8)
                if (text.length > maxChars) {
                    text.take(maxChars) + "\n...[truncated for memory budget]"
                } else {
                    text
                }
            }
        }

    suspend fun deleteFile(relativePath: String): Result<Boolean> =
        withContext(Dispatchers.IO) {
            runCatching {
                val target = resolveConfinedFile(relativePath)
                require(target.exists()) { "File does not exist: $relativePath" }
                val deleted = target.deleteRecursively()
                refreshSync()
                deleted
            }
        }

    suspend fun listFilesSummary(): String = withContext(Dispatchers.IO) {
        val entries = refreshSync().filter { !it.isDirectory }
        if (entries.isEmpty()) {
            "Workspace is empty."
        } else {
            entries.joinToString("\n") { "${it.relativePath} (${it.sizeBytes} bytes)" }
        }
    }

    private fun resolveConfinedFile(relativePath: String): File {
        val cleaned = relativePath.trim().trimStart('/').ifBlank { "drafts/untitled.txt" }
        val candidate = File(rootDir, cleaned).canonicalFile
        val rootCanonical = rootDir.canonicalFile
        val rootPrefix = rootCanonical.path + File.separator
        if (candidate.path != rootCanonical.path && !candidate.path.startsWith(rootPrefix)) {
            throw SecurityException("Path traversal blocked outside sandboxed workspace: $relativePath")
        }
        return candidate
    }

    companion object {
        private const val WORKSPACE_ROOT_FOLDER = "agent_workspace"
        private const val MAX_FILE_BYTES = 512 * 1024
        private val SUBFOLDERS = listOf("research", "drafts", "scripts", "media", "history")
    }
}

