package com.virtualos.agent.limbs.accessibility

import android.content.Context
import android.content.Intent
import android.provider.Settings
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import java.lang.ref.WeakReference

/**
 * Thread-safe bridge between the AgentOrchestrator and Android's AccessibilityService.
 */
object AccessibilityBridge {

    private var serviceRef: WeakReference<AgentAccessibilityService>? = null

    private val _isConnected = MutableStateFlow(false)
    val isConnected: StateFlow<Boolean> = _isConnected.asStateFlow()

    private val _activePackage = MutableStateFlow("")
    val activePackage: StateFlow<String> = _activePackage.asStateFlow()

    private val _lastScreenSnapshot = MutableStateFlow("Accessibility service inactive")
    val lastScreenSnapshot: StateFlow<String> = _lastScreenSnapshot.asStateFlow()

    internal fun attach(service: AgentAccessibilityService) {
        serviceRef = WeakReference(service)
        _isConnected.value = true
    }

    internal fun detach() {
        serviceRef = null
        _isConnected.value = false
    }

    internal fun updateActiveWindow(packageName: String) {
        _activePackage.value = packageName
    }

    fun readScreenTree(maxNodes: Int = 55): Result<String> {
        val service = serviceRef?.get() ?: return Result.failure(
            IllegalStateException("Accessibility Service is not enabled. Enable 'KaryoOS Virtual Limbs Service' in Android Settings.")
        )
        val snapshot = service.captureUiTreeSummary(maxNodes)
        _lastScreenSnapshot.value = snapshot
        return Result.success(snapshot)
    }

    fun clickNode(targetTextOrId: String): Result<String> {
        val service = serviceRef?.get() ?: return Result.failure(
            IllegalStateException("Accessibility Service is not enabled.")
        )
        return service.clickNodeByQuery(targetTextOrId)
    }

    fun typeText(targetTextOrId: String, text: String): Result<String> {
        val service = serviceRef?.get() ?: return Result.failure(
            IllegalStateException("Accessibility Service is not enabled.")
        )
        return service.setTextOnNode(targetTextOrId, text)
    }

    fun scrollScreen(forward: Boolean): Result<String> {
        val service = serviceRef?.get() ?: return Result.failure(
            IllegalStateException("Accessibility Service is not enabled.")
        )
        return service.scrollActiveWindow(forward)
    }

    fun performBack(): Result<String> {
        val service = serviceRef?.get() ?: return Result.failure(
            IllegalStateException("Accessibility Service is not enabled.")
        )
        val ok = service.performGlobalBack()
        return if (ok) Result.success("Performed GLOBAL_ACTION_BACK")
        else Result.failure(IllegalStateException("GLOBAL_ACTION_BACK failed"))
    }

    fun launchAppByPackageOrName(context: Context, query: String): Result<String> {
        val pm = context.packageManager
        val directIntent = pm.getLaunchIntentForPackage(query.trim())
        if (directIntent != null) {
            directIntent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
            context.startActivity(directIntent)
            return Result.success("Launched package $query")
        }

        val mainIntent = Intent(Intent.ACTION_MAIN, null).apply {
            addCategory(Intent.CATEGORY_LAUNCHER)
        }
        val apps = pm.queryIntentActivities(mainIntent, 0)
        val match = apps.firstOrNull { resolveInfo ->
            val label = resolveInfo.loadLabel(pm).toString()
            label.contains(query, ignoreCase = true) ||
                resolveInfo.activityInfo.packageName.contains(query, ignoreCase = true)
        } ?: return Result.failure(IllegalStateException("No installed app matching '$query'"))

        val launchIntent = pm.getLaunchIntentForPackage(match.activityInfo.packageName)
            ?: return Result.failure(IllegalStateException("Cannot create launch intent for ${match.activityInfo.packageName}"))
        launchIntent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
        context.startActivity(launchIntent)
        return Result.success("Launched ${match.loadLabel(pm)} (${match.activityInfo.packageName})")
    }

    fun openAccessibilitySettings(context: Context) {
        val intent = Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS).apply {
            addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
        }
        context.startActivity(intent)
    }
}

package com.virtualos.agent.limbs.accessibility

import android.accessibilityservice.AccessibilityService
import android.accessibilityservice.GestureDescription
import android.graphics.Path
import android.graphics.Rect
import android.os.Bundle
import android.view.accessibility.AccessibilityEvent
import android.view.accessibility.AccessibilityNodeInfo

/**
 * Android AccessibilityService acting as the agent's OS-level sensory and motor limb.
 * Only inspects and acts on screen elements when explicitly invoked by the agent orchestrator.
 */
class AgentAccessibilityService : AccessibilityService() {

    override fun onServiceConnected() {
        super.onServiceConnected()
        AccessibilityBridge.attach(this)
    }

    override fun onAccessibilityEvent(event: AccessibilityEvent?) {
        val pkg = event?.packageName?.toString().orEmpty()
        if (pkg.isNotBlank()) {
            AccessibilityBridge.updateActiveWindow(pkg)
        }
    }

    override fun onInterrupt() {
        // Required override; bridge remains attached until unbind.
    }

    override fun onDestroy() {
        AccessibilityBridge.detach()
        super.onDestroy()
    }

    fun captureUiTreeSummary(maxNodes: Int = 55): String {
        val root = rootInActiveWindow ?: return "No active window root available."
        val lines = mutableListOf<String>()
        val queue = ArrayDeque<Pair<AccessibilityNodeInfo, Int>>()
        queue.add(root to 0)

        try {
            while (queue.isNotEmpty() && lines.size < maxNodes) {
                val (node, depth) = queue.removeFirst()
                val text = node.text?.toString()?.trim().orEmpty()
                val desc = node.contentDescription?.toString()?.trim().orEmpty()
                val resId = node.viewIdResourceName?.substringAfterLast('/')?.orEmpty().orEmpty()

                val isUseful = text.isNotBlank() || desc.isNotBlank() ||
                    node.isClickable || node.isEditable || node.isScrollable

                if (isUseful) {
                    val bounds = Rect().also { node.getBoundsInScreen(it) }
                    val flags = buildList {
                        if (node.isClickable) add("click")
                        if (node.isEditable) add("edit")
                        if (node.isScrollable) add("scroll")
                    }.joinToString(",")
                    val indent = "  ".repeat(depth.coerceAtMost(4))
                    val classSimple = node.className?.toString()?.substringAfterLast('.') ?: "View"
                    lines.add(
                        "$indent[$classSimple] id='$resId' text='${text.take(48)}' desc='${desc.take(36)}' ($flags) @${bounds.centerX()},${bounds.centerY()}"
                    )
                }

                for (i in 0 until node.childCount) {
                    node.getChild(i)?.let { child ->
                        queue.add(child to depth + 1)
                    }
                }
            }
        } finally {
            root.recycle()
        }

        return if (lines.isEmpty()) "Window has no interactive nodes." else lines.joinToString("\n")
    }

    fun clickNodeByQuery(query: String): Result<String> {
        val root = rootInActiveWindow ?: return Result.failure(IllegalStateException("No active window"))
        val match = findNode(root, query) ?: return Result.failure(
            IllegalStateException("No UI node matched '$query'")
        )

        var current: AccessibilityNodeInfo? = match
        while (current != null && !current.isClickable) {
            current = current.parent
        }

        val clicked = if (current != null && current.isClickable) {
            current.performAction(AccessibilityNodeInfo.ACTION_CLICK)
        } else {
            val rect = Rect()
            match.getBoundsInScreen(rect)
            dispatchTapGesture(rect.centerX().toFloat(), rect.centerY().toFloat())
        }

        return if (clicked) Result.success("Clicked node matching '$query'")
        else Result.failure(IllegalStateException("Failed to click '$query'"))
    }

    fun setTextOnNode(query: String, value: String): Result<String> {
        val root = rootInActiveWindow ?: return Result.failure(IllegalStateException("No active window"))
        val target = if (query.isBlank()) {
            findFirstEditableNode(root)
        } else {
            findNode(root, query) ?: findFirstEditableNode(root)
        } ?: return Result.failure(IllegalStateException("No editable UI node matched '$query'"))

        target.performAction(AccessibilityNodeInfo.ACTION_FOCUS)
        val args = Bundle().apply {
            putCharSequence(AccessibilityNodeInfo.ACTION_ARGUMENT_SET_TEXT_CHARSEQUENCE, value)
        }
        val ok = target.performAction(AccessibilityNodeInfo.ACTION_SET_TEXT, args)
        return if (ok) Result.success("Typed into node '$query'")
        else Result.failure(IllegalStateException("ACTION_SET_TEXT rejected on '$query'"))
    }

    fun scrollActiveWindow(forward: Boolean): Result<String> {
        val root = rootInActiveWindow ?: return Result.failure(IllegalStateException("No active window"))
        val scrollable = findFirstScrollableNode(root)
            ?: return Result.failure(IllegalStateException("No scrollable container in active window"))
        val action = if (forward) {
            AccessibilityNodeInfo.ACTION_SCROLL_FORWARD
        } else {
            AccessibilityNodeInfo.ACTION_SCROLL_BACKWARD
        }
        val ok = scrollable.performAction(action)
        return if (ok) Result.success(if (forward) "Scrolled forward" else "Scrolled backward")
        else Result.failure(IllegalStateException("Scroll action returned false"))
    }

    fun performGlobalBack(): Boolean = performGlobalAction(GLOBAL_ACTION_BACK)

    private fun dispatchTapGesture(x: Float, y: Float): Boolean {
        val path = Path().apply { moveTo(x, y) }
        val stroke = GestureDescription.StrokeDescription(path, 0L, 65L)
        val gesture = GestureDescription.Builder().addStroke(stroke).build()
        return dispatchGesture(gesture, null, null)
    }

    private fun findNode(root: AccessibilityNodeInfo, query: String): AccessibilityNodeInfo? {
        val queue = ArrayDeque<AccessibilityNodeInfo>()
        queue.add(root)
        while (queue.isNotEmpty()) {
            val node = queue.removeFirst()
            val text = node.text?.toString().orEmpty()
            val desc = node.contentDescription?.toString().orEmpty()
            val resId = node.viewIdResourceName.orEmpty()
            if (text.contains(query, ignoreCase = true) ||
                desc.contains(query, ignoreCase = true) ||
                resId.contains(query, ignoreCase = true)
            ) {
                return node
            }
            for (i in 0 until node.childCount) {
                node.getChild(i)?.let { queue.add(it) }
            }
        }
        return null
    }

    private fun findFirstEditableNode(root: AccessibilityNodeInfo): AccessibilityNodeInfo? {
        val queue = ArrayDeque<AccessibilityNodeInfo>()
        queue.add(root)
        while (queue.isNotEmpty()) {
            val node = queue.removeFirst()
            if (node.isEditable) return node
            for (i in 0 until node.childCount) {
                node.getChild(i)?.let { queue.add(it) }
            }
        }
        return null
    }

    private fun findFirstScrollableNode(root: AccessibilityNodeInfo): AccessibilityNodeInfo? {
        val queue = ArrayDeque<AccessibilityNodeInfo>()
        queue.add(root)
        while (queue.isNotEmpty()) {
            val node = queue.removeFirst()
            if (node.isScrollable) return node
            for (i in 0 until node.childCount) {
                node.getChild(i)?.let { queue.add(it) }
            }
        }
        return null
    }
}

package com.virtualos.agent.limbs.media

import android.content.Context
import android.graphics.Bitmap
import android.graphics.Canvas
import android.graphics.Color
import android.graphics.Paint
import android.net.Uri
import androidx.annotation.OptIn
import androidx.media3.common.MediaItem
import androidx.media3.common.MimeTypes
import androidx.media3.common.util.UnstableApi
import androidx.media3.effect.BitmapOverlay
import androidx.media3.effect.OverlayEffect
import androidx.media3.effect.Presentation
import androidx.media3.transformer.Composition
import androidx.media3.transformer.EditedMediaItem
import androidx.media3.transformer.Effects
import androidx.media3.transformer.ExportException
import androidx.media3.transformer.ExportResult
import androidx.media3.transformer.Transformer
import kotlinx.coroutines.CompletableDeferred
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import java.io.File

/**
 * Hardware-accelerated on-device Video Editing Limb powered by Jetpack Media3 Transformer.
 * Supports trimming, resolution compression (480p/720p/1080p), audio removal, and text watermarks.
 */
class VideoEditorLimb(private val context: Context) {

    private val mediaDir: File = File(context.filesDir, "agent_workspace/media").apply {
        if (!exists()) mkdirs()
    }

    @OptIn(UnstableApi::class)
    suspend fun trimVideo(
        sourceUriOrPath: String,
        startMs: Long,
        endMs: Long,
        outputName: String = "trimmed_${System.currentTimeMillis()}.mp4"
    ): Result<String> = runTransform(
        mediaItem = MediaItem.Builder()
            .setUri(resolveUri(sourceUriOrPath))
            .setClippingConfiguration(
                MediaItem.ClippingConfiguration.Builder()
                    .setStartPositionMs(startMs.coerceAtLeast(0L))
                    .setEndPositionMs(endMs.coerceAtLeast(startMs + 500L))
                    .build()
            )
            .build(),
        effects = Effects(emptyList(), emptyList()),
        removeAudio = false,
        outputFile = File(mediaDir, sanitizeName(outputName))
    )

    @OptIn(UnstableApi::class)
    suspend fun resizeAndCompressVideo(
        sourceUriOrPath: String,
        targetHeightPx: Int = 720,
        outputName: String = "compressed_${targetHeightPx}p_${System.currentTimeMillis()}.mp4"
    ): Result<String> {
        val presentation = Presentation.createForHeight(targetHeightPx.coerceIn(360, 1080))
        return runTransform(
            mediaItem = MediaItem.fromUri(resolveUri(sourceUriOrPath)),
            effects = Effects(emptyList(), listOf(presentation)),
            removeAudio = false,
            outputFile = File(mediaDir, sanitizeName(outputName))
        )
    }

    @OptIn(UnstableApi::class)
    suspend fun muteVideo(
        sourceUriOrPath: String,
        outputName: String = "muted_${System.currentTimeMillis()}.mp4"
    ): Result<String> = runTransform(
        mediaItem = MediaItem.fromUri(resolveUri(sourceUriOrPath)),
        effects = Effects(emptyList(), emptyList()),
        removeAudio = true,
        outputFile = File(mediaDir, sanitizeName(outputName))
    )

    @OptIn(UnstableApi::class)
    suspend fun addTextWatermark(
        sourceUriOrPath: String,
        watermarkText: String,
        outputName: String = "watermarked_${System.currentTimeMillis()}.mp4"
    ): Result<String> {
        val bitmap = renderTextBitmap(watermarkText.ifBlank { "KaryoOS" })
        val overlay = BitmapOverlay.createFromBitmap(bitmap)
        val overlayEffect = OverlayEffect(listOf(overlay))
        return runTransform(
            mediaItem = MediaItem.fromUri(resolveUri(sourceUriOrPath)),
            effects = Effects(emptyList(), listOf(overlayEffect)),
            removeAudio = false,
            outputFile = File(mediaDir, sanitizeName(outputName))
        )
    }

    @OptIn(UnstableApi::class)
    private suspend fun runTransform(
        mediaItem: MediaItem,
        effects: Effects,
        removeAudio: Boolean,
        outputFile: File
    ): Result<String> = withContext(Dispatchers.Main) {
        if (outputFile.exists()) outputFile.delete()
        val deferred = CompletableDeferred<Result<String>>()

        val edited = EditedMediaItem.Builder(mediaItem)
            .setRemoveAudio(removeAudio)
            .setEffects(effects)
            .build()

        val transformer = Transformer.Builder(context)
            .setVideoMimeType(MimeTypes.VIDEO_H264)
            .setAudioMimeType(MimeTypes.AUDIO_AAC)
            .addListener(object : Transformer.Listener {
                override fun onCompleted(composition: Composition, result: ExportResult) {
                    val sizeKb = outputFile.length() / 1024L
                    deferred.complete(
                        Result.success("Exported media/${outputFile.name} (${sizeKb} KB)")
                    )
                }

                override fun onError(
                    composition: Composition,
                    result: ExportResult,
                    exception: ExportException
                ) {
                    deferred.complete(
                        Result.failure(IllegalStateException("Media3 export failed: ${exception.message}"))
                    )
                }
            })
            .build()

        transformer.start(edited, outputFile.absolutePath)
        deferred.await()
    }

    private fun resolveUri(input: String): Uri {
        val trimmed = input.trim()
        return if (trimmed.startsWith("content://") || trimmed.startsWith("file://") || trimmed.startsWith("https://")) {
            Uri.parse(trimmed)
        } else {
            val localFile = File(context.filesDir, "agent_workspace/${trimmed.trimStart('/')}")
            Uri.fromFile(localFile)
        }
    }

    private fun sanitizeName(name: String): String {
        val base = name.substringAfterLast('/').replace(Regex("[^a-zA-Z0-9._-]"), "_")
        return if (base.endsWith(".mp4")) base else "$base.mp4"
    }

    private fun renderTextBitmap(text: String): Bitmap {
        val width = 480
        val height = 84
        val bitmap = Bitmap.createBitmap(width, height, Bitmap.Config.ARGB_8888)
        val canvas = Canvas(bitmap)
        val bgPaint = Paint(Paint.ANTI_ALIAS_FLAG).apply {
            color = Color.argb(150, 15, 23, 42)
        }
        canvas.drawRoundRect(8f, 8f, width - 8f, height - 8f, 16f, 16f, bgPaint)
        val textPaint = Paint(Paint.ANTI_ALIAS_FLAG).apply {
            color = Color.WHITE
            textSize = 28f
            isFakeBoldText = true
        }
        canvas.drawText(text.take(28), 24f, 52f, textPaint)
        return bitmap
    }
}

package com.virtualos.agent.limbs.os

import android.content.ClipData
import android.content.ClipboardManager
import android.content.Context
import android.content.Intent

/**
 * OS-level Clipboard & Intent Share Limb for moving text/drafts across Android apps safely.
 */
class ClipboardAndIntentLimb(private val context: Context) {

    fun copyToClipboard(label: String, text: String): Result<String> {
        val clipboard = context.getSystemService(Context.CLIPBOARD_SERVICE) as ClipboardManager
        clipboard.setPrimaryClip(ClipData.newPlainText(label.ifBlank { "KaryoOS" }, text))
        return Result.success("Copied ${text.length} chars to system clipboard")
    }

    fun shareTextIntent(title: String, body: String): Result<String> {
        val sendIntent = Intent(Intent.ACTION_SEND).apply {
            type = "text/plain"
            putExtra(Intent.EXTRA_SUBJECT, title)
            putExtra(Intent.EXTRA_TEXT, body)
        }
        val chooser = Intent.createChooser(sendIntent, title.ifBlank { "Share via KaryoOS" }).apply {
            addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
        }
        context.startActivity(chooser)
        return Result.success("Opened Android share sheet for '$title'")
    }
}

package com.virtualos.agent.limbs.store

import android.content.Context
import android.content.Intent
import android.content.pm.PackageManager
import android.net.Uri
import com.virtualos.agent.data.security.EncryptedVaultStore
import com.virtualos.agent.domain.model.VirtualAppEntry
import kotlinx.coroutines.flow.StateFlow

/**
 * Built-in Virtual Play Store & Isolated App Manager.
 * Searches curated Play Store apps (WhatsApp, imo, Telegram, Dialer, etc.),
 * installs them into KaryoOS's isolated Virtual Phone drawer (with web/container fallback),
 * and can launch Google Play Store intent + Accessibility auto-install on real Android devices.
 */
class PlayStoreLimb(
    private val context: Context,
    private val vaultStore: EncryptedVaultStore
) {
    val installedVirtualApps: StateFlow<List<VirtualAppEntry>> = vaultStore.virtualApps

    fun searchCatalog(query: String): List<VirtualAppEntry> {
        val q = query.trim().lowercase()
        val catalog = DEFAULT_CATALOG
        val matched = if (q.isBlank()) {
            catalog
        } else {
            catalog.filter {
                it.appName.lowercase().contains(q) ||
                    it.packageId.lowercase().contains(q) ||
                    it.category.lowercase().contains(q)
            }
        }
        return if (matched.isNotEmpty()) {
            matched
        } else {
            val cleanPkg = "com.virtualos.app." + q.replace(Regex("[^a-z0-9]"), "")
            listOf(
                VirtualAppEntry(
                    packageId = cleanPkg,
                    appName = query.trim().replaceFirstChar { it.uppercase() },
                    category = "Play Store Custom",
                    webFallbackUrl = "https://play.google.com/store/search?q=${Uri.encode(query)}&c=apps",
                    version = "Latest"
                )
            )
        }
    }

    fun installApp(queryOrPackage: String, triggerSystemPlayStore: Boolean = true): Result<VirtualAppEntry> {
        val candidate = searchCatalog(queryOrPackage).first()
        val installed = candidate.copy(
            installedInVirtualPhone = true,
            installedAtMs = System.currentTimeMillis()
        )
        vaultStore.upsertVirtualApp(installed)

        if (triggerSystemPlayStore && !isPackageInstalledOnHost(candidate.packageId)) {
            runCatching {
                val playIntent = Intent(
                    Intent.ACTION_VIEW,
                    Uri.parse("market://details?id=${candidate.packageId}")
                ).apply {
                    addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
                }
                context.startActivity(playIntent)
            }
        }

        return Result.success(installed)
    }

    fun isPackageInstalledOnHost(packageId: String): Boolean {
        return runCatching {
            context.packageManager.getPackageInfo(packageId, PackageManager.PackageInfoFlags.of(0))
            true
        }.getOrElse {
            runCatching {
                @Suppress("DEPRECATION")
                context.packageManager.getPackageInfo(packageId, 0)
                true
            }.getOrDefault(false)
        }
    }

    companion object {
        val DEFAULT_CATALOG = listOf(
            VirtualAppEntry("com.whatsapp", "WhatsApp", "Messaging & Calling", "https://web.whatsapp.com", "2.24.22"),
            VirtualAppEntry("com.imo.android.imoim", "imo HD Video Calls", "Calling & Chat", "https://imo.im", "2025.02"),
            VirtualAppEntry("org.telegram.messenger", "Telegram", "Messaging", "https://web.telegram.org", "11.5.0"),
            VirtualAppEntry("com.facebook.orca", "Messenger", "Social & Calling", "https://www.messenger.com", "485.0"),
            VirtualAppEntry("com.facebook.katana", "Facebook", "Social Media", "https://m.facebook.com", "490.0"),
            VirtualAppEntry("com.google.android.dialer", "Virtual Phone & Calling", "Calling", "https://voice.google.com", "152.0"),
            VirtualAppEntry("com.google.android.gm", "Gmail", "Email", "https://mail.google.com", "2025.01"),
            VirtualAppEntry("com.google.android.youtube", "YouTube", "Media", "https://m.youtube.com", "19.45"),
            VirtualAppEntry("com.lemon.lvoverseas", "CapCut Video Editor", "Video Editing", "https://www.capcut.com/editor", "13.2")
        )
    }
